window.FILM_WORK_PROMPTS={"work_id":"src-dbd54692f4a35d40","records":[{"work_id":"src-dbd54692f4a35d40","frame_id":"VS-c2a7441a01e31ec0","source_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-chairs.jpg","source_page":"https://www.the-frame.com/blog/2016/12/challenge-week-47-the-ghost-and-mrs-muir/","scene":"黑白室内场景，一男一女相对而坐。女子位于左侧，男子位于右侧，两人身体前倾，视线交汇。背景为带有装饰性浮雕的壁炉，两侧可见花纹织物覆盖的家具边缘。","analysis":"构图呈左右对称式对峙，人物占据画面主体约三分之二。女子可见上半身，男子可见上半身及大腿部分。镜头平视，无俯仰。明暗对比强烈，女子面部及浅色上衣受光明显，男子深色衣物与背景阴影融合，仅面部轮廓有高光。整体为黑白灰层次，无彩色信息。","prompt":"黑白低分辨率室内静帧，一男一女相对而坐。左侧女子梳盘发，穿浅色碎花长袖上衣，身体前倾，双手置于身前。右侧男子留胡须，穿深色西装，身体大幅前倾，面部朝向女子。背景为石质壁炉，上方有圆形浮雕装饰。画面两侧边缘可见带花纹的织物。光线从左侧打入，照亮女子面部与上衣，男子面部有侧光，其余部分处于阴影中。人物占据画面主要空间，环境作为背景衬托。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-15T13:50:27+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-chairs.jpg","observed_dimensions":[600,338],"source_thumbnail_dimensions":[600,338],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-2a85abdade69ba60","origin":"visual"},{"work_id":"src-dbd54692f4a35d40","frame_id":"VS-4b9ea1f6b1dffb91","source_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-listening.jpg","source_page":"https://www.the-frame.com/blog/2016/12/challenge-week-47-the-ghost-and-mrs-muir/","scene":"黑白室内场景，前景一名穿围裙的女子站立，身旁一名儿童倚靠门框，背景透过门洞可见餐桌及站立的人影。","analysis":"画面采用前景与背景的空间分割构图。前景人物占据画面左侧及中部，女子仅上半身可见，儿童为半身像，二者身形较大。背景通过右侧门洞展现，人物身形较小，形成明显的远近比例对比。光线从左侧射入，在人物面部和围裙上形成高光，右侧门框及背景区域处于阴影中，明暗对比强烈，层次分明。","prompt":"黑白电影风格静帧，低分辨率质感。画面左侧前景，一名女子站立，身穿深色条纹长袖衬衫，外罩白色围裙，头发盘起，身体微侧，面部朝向右侧。其身前右侧，一名儿童身穿深色上衣，身体倚靠在垂直的门框边缘，头部微侧。背景右侧通过门洞可见另一空间，有一张铺着浅色桌布的圆桌，桌上摆放着若干瓶罐，桌旁站立着一名身穿深色长衣的人影，旁边还有模糊的坐姿人物轮廓。左侧背景可见带有玻璃门的白色橱柜，内部隐约可见器皿。整体光影对比强烈，左侧受光，右侧门框及背景较暗，营造出室内生活场景的纵深感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-15T13:52:00+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-listening.jpg","observed_dimensions":[600,453],"source_thumbnail_dimensions":[600,453],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-cce18802ba51dd37","origin":"visual"},{"work_id":"src-dbd54692f4a35d40","frame_id":"VS-adb66be5db1207e5","source_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-praying.jpg","source_page":"https://www.the-frame.com/blog/2016/12/challenge-week-47-the-ghost-and-mrs-muir/","scene":"室内卧室一角，一名穿深色长裙的女子站立在床尾，低头看向床上。床上坐着一名穿浅色上衣的女孩，旁边卧着一只毛茸茸的狗。背景可见一扇木门和墙上的壁灯。","analysis":"画面主体为站立的女子与床上的女孩及狗，人物上半身及下半身轮廓清晰。女子身形高大，占据画面右侧主要空间，女孩与狗位于前景床铺上，形成高低对比。光线从左侧射入，在墙面投下清晰的人物与家具阴影，明暗对比强烈。黑白影调，衣物深色与浅色形成视觉分割，环境陈设如床头柱和背景门框提供了空间深度。","prompt":"黑白室内场景，画面右侧站立一名身穿深色长袖连衣裙的女子，领口与袖口有浅色装饰，她低头看向床铺方向。前景床铺上坐着一名穿浅色上衣的女孩，双手交叠，旁边卧着一只毛发蓬松的狗。背景左侧有一扇浅色木门，墙面挂有壁灯，右侧可见深色家具轮廓。光线从左侧打入，在墙上形成明显的投影，整体光影对比分明，营造出静谧的室内氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-15T13:53:55+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-praying.jpg","observed_dimensions":[600,457],"source_thumbnail_dimensions":[600,457],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-358e3d0fe74d7a82","origin":"visual"},{"work_id":"src-dbd54692f4a35d40","frame_id":"VS-8624bea144b27add","source_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-bed1.jpg","source_page":"https://www.the-frame.com/blog/2016/12/challenge-week-47-the-ghost-and-mrs-muir/","scene":"黑白画面中，一名留胡须的男子俯身向下，面部贴近一名仰面躺着的人。背景为模糊的室内环境，可见垂直的窗框或门框结构及远处的亮区。","analysis":"构图紧凑，主体占据画面右侧及下方。男子仅上半身及头部可见，身体前倾，头部位于画面右上方；躺着的人仅头部及肩部可见，位于左下方。男子面部受光，轮廓清晰，胡须明显；躺着的人面部大部分处于阴影中。背景虚化，明暗对比强烈，光源似乎来自左后方，形成逆光或侧逆光效果，人物边缘有高光。","prompt":"黑白低分辨率画面，高对比度光影。画面右侧一名深色头发、留络腮胡的男子俯身向下，身穿深色高领衣物，面部轮廓在侧光下清晰，神情专注。画面左下方一名人物仰面躺着，头部枕在浅色物体上，面部大部分处于阴影中，仅轮廓可见。两人距离极近，视线交汇。背景模糊，可见垂直的窗框或门框线条，远处有明亮的窗户或光源，形成逆光效果。整体氛围压抑、亲密且充满张力，景深极浅，焦点集中在男子面部。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-15T13:55:13+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-bed1.jpg","observed_dimensions":[600,453],"source_thumbnail_dimensions":[600,453],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-de8f1fa51b5b44b8","origin":"visual"},{"work_id":"src-dbd54692f4a35d40","frame_id":"VS-5cb50de99ba2b171","source_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-together.jpg","source_page":"https://www.the-frame.com/blog/2016/12/challenge-week-47-the-ghost-and-mrs-muir/","scene":"室内视角透过敞开的双扇白门，可见门外一对男女背影站立在延伸向远方的栈道上，背景是明亮的云层天空。","analysis":"构图采用门框式取景，左右白色门扇形成前景框架。门外人物全身可见，左侧人物着长裙，右侧人物着深色套装，两人并排站立，身形在明亮背景中呈剪影状。环境占比大，天空云层占据画面上半部，栈道延伸至人物脚下。明暗对比强烈，室内昏暗，门外高亮，右侧墙壁有一盏壁灯发出局部亮光。","prompt":"黑白画面，室内视角透过敞开的双扇白色木门向外看。门框内是一对男女的背影，左侧人物穿长裙，右侧人物穿深色西装，两人并排站立在一条延伸向远方的木质栈道上。背景是明亮的天空和云层，人物呈剪影效果。室内墙壁昏暗，右侧墙上有一盏亮着的壁灯，右下角可见家具一角。画面具有强烈的明暗对比，门框形成画中画构图，整体氛围静谧。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-15T13:56:06+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-together.jpg","observed_dimensions":[600,442],"source_thumbnail_dimensions":[600,442],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-8add0ee49adc0cb3","origin":"visual"},{"work_id":"src-dbd54692f4a35d40","frame_id":"VS-b0fafefae679a531","source_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-sanders.jpg","source_page":"https://www.the-frame.com/blog/2016/12/challenge-week-47-the-ghost-and-mrs-muir/","scene":"黑白室内场景，左侧一名戴帽男子站立，双手插兜；右侧一名女子侧身站立，头戴高耸羽毛装饰，手持手包。背景可见书架、桌椅及门框。","analysis":"构图将两人分置左右，形成视觉平衡。人物均为上半身至大腿可见，男子身形较宽，女子身形修长。光线从左侧射入，在人物面部和衣物上形成明暗对比，背景处于较暗的阴影中。画面层次分明，前景人物清晰，背景家具轮廓可辨。","prompt":"黑白电影静帧，室内场景。左侧一名男子站立，身穿深色西装，头戴浅色圆顶礼帽，双手插在裤兜里，身体微侧向右。右侧一名女子侧身站立，面向左方，头戴夸张的高耸羽毛头饰，身穿格纹外套，领口和袖口有深色装饰，左手持深色手包。背景左侧有书架和桌子，中间有一把深色椅子，右侧是门框和墙壁。光线从左侧窗户射入，照亮人物面部和衣物，背景较暗，明暗对比强烈。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-15T14:33:37+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-sanders.jpg","observed_dimensions":[600,457],"source_thumbnail_dimensions":[600,457],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-3f99159ee7bfe953","origin":"visual"},{"work_id":"src-dbd54692f4a35d40","frame_id":"VS-18a0723285a9bd34","source_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-portrait.jpg","source_page":"https://www.the-frame.com/blog/2016/12/challenge-week-47-the-ghost-and-mrs-muir/","scene":"黑白画面中，左侧是一幅巨大的男性半身肖像画，画中人物戴帽穿深色大衣。右侧前景站着一位女性，身穿浅色高领上衣，背景为素净的墙面。","analysis":"构图采用左右分割，左侧肖像画占据约一半画面宽度，右侧女性位于前景。人物均仅显示上半身，女性头部略低于画中人物。光线从右侧打入，在女性面部和肩部形成高光，并在其身后的墙壁上投下清晰的阴影。整体明暗对比强烈，左侧画作色调深沉，右侧人物衣着明亮。","prompt":"黑白摄影风格，画面左侧是一幅巨大的男性肖像画，画中男子戴着深色大檐帽，身穿厚重深色大衣，背景为模糊的暗色风景。画面右侧前景站立着一位女性，她留着深色盘发，身穿浅色高领长袖上衣，领口处有深色装饰细节。女性身体微侧，面部朝向左前方。强烈的侧光从右侧照射，使女性面部和衣物呈现亮白色，并在其身后的浅色墙壁上投下明显的黑色阴影。整体画面明暗对比分明，左侧暗部与右侧亮部形成视觉平衡。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-15T14:35:06+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-portrait.jpg","observed_dimensions":[600,367],"source_thumbnail_dimensions":[600,367],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-2bcc28e566389ca3","origin":"visual"},{"work_id":"src-dbd54692f4a35d40","frame_id":"VS-5402daa16e10ce16","source_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-sanders-umbrella.jpg","source_page":"https://www.the-frame.com/blog/2016/12/challenge-week-47-the-ghost-and-mrs-muir/","scene":"黑白画面中，一男一女并肩站立于建筑门前。男子手持一把撑开的深色大伞，伞面覆盖在两人头顶上方。左侧墙面可见壁灯与矩形牌匾，右侧为木质门板。","analysis":"画面截取人物腰部以上，两人占据画面中心及右侧主要区域。男子身形高大，位于右侧，深色西装与浅色礼帽形成对比；女子位于左侧，身形较小，头戴装饰复杂的帽子，身着格纹外套。背景墙面与门板占据约三分之一空间，左侧壁灯与牌匾提供环境细节。光线从左侧照射，在墙面形成阴影，整体明暗对比强烈，黑白影调层次分明。","prompt":"黑白摄影风格，画面呈现一男一女在建筑门前的半身像。右侧男子身形高大，头戴浅色宽檐礼帽，身穿深色西装，右手握持一把撑开的深色大伞，伞面占据画面右上角。左侧女子身形较小，头戴装饰有羽毛或丝带的深色帽子，身穿格纹外套，两人并肩站立，男子身体略微倾向女子。背景左侧为粗糙质感的石质墙面，墙上安装有复古壁灯和两块矩形牌匾；右侧为深色木质门板。光线从左侧射入，在墙面投下清晰阴影，人物面部与衣物受光明显，整体呈现高对比度的黑白影调。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-15T14:36:42+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://www.the-frame.com/blog/wp-content/uploads/2016/12/tf-sanders-umbrella.jpg","observed_dimensions":[600,431],"source_thumbnail_dimensions":[600,431],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-e0f1880ae535b01e","origin":"visual"}]};